fn fresh_state_with_enemy(hp: i32) -> (CombatState, CreatureUid) {
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    let id = NonZeroU32::new(1).expect("non-zero");
    state.creatures.push(Creature {
        id,
        current_hp: hp,
        max_hp: hp,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("Nibbit"),
        ai: None,
    });
    let uid = CreatureUid(id);
    state.enemy_uids.push(uid);
    (state, uid)
}

fn push_play_card(
    state: &mut CombatState,
    card_id: CardId,
    base_damage: i32,
    base_block: i32,
) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage,
        base_block,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.play.push(uid);
    uid
}

/// Push a fresh card into the player's HAND (not the play pile). Used by
/// the HeirloomHammer clone-into-hand fixtures.
fn push_hand_card(state: &mut CombatState, card_id: CardId) -> sts2_core::CardUid {
    let raw = u32::try_from(state.cards.len() + 1).expect("cards len fits in u32");
    let uid = sts2_core::CardUid::new(raw).expect("non-zero uid");
    state.cards.push(Card {
        uid,
        card_id,
        cost: 1,
        card_type: CardType::Attack,
        target_type: TargetType::Enemy,
        upgraded: false,
        base_damage: 0,
        base_block: 0,
        combat_vars: sts2_core::cards::CombatVars::new(),
        enchantments: sts2_core::cards::CardEnchantments::new(),
        tags: CardTags::NONE,
        energy_spent: 0,
        base_replay_count: 0,
        keyword_override: None,
        affliction: None,
    });
    state.player.hand.push(uid);
    uid
}

/// Mint a card FROM ITS REAL SPEC (correct `card_type` / `base_block` /
/// keywords) into the player's HAND. Unlike [`push_hand_card`] (which hardcodes
/// an Attack POD), this is required for the DecisionsDecisions Skill-filter +
/// auto-play fixtures, where the auto-played Skill's own POD `base_block` and
/// `card_type` are load-bearing (e.g. DefendRegent must carry `base_block = 5`).
fn push_hand_skill(state: &mut CombatState, id: CardId) -> sts2_core::CardUid {
    let mut card = crate::cards::spec_index::card_pod_from_id(id, false).expect("spec exists");
    let raw = u32::try_from(state.cards.len() + 1).expect("fits");
    let uid = sts2_core::CardUid::new(raw).expect("nz");
    card.uid = uid;
    state.cards.push(card);
    state.player.hand.push(uid);
    uid
}

