#[test]
fn regent_power_amounts_scale_with_upgrade() {
    // C# OnUpgrade bumps: Patter Vigor 2->3, Resonance Strength 1->2,
    // PillarOfCreation 3->4. Bead mwts2.
    install_pool();
    let player_power = |card: CardId, kind: PowerKind, upgraded: bool| -> Option<i32> {
        let (mut state, enemy) = fresh_state_with_enemy(200);
        let _ = push_play_card(&mut state, card, 0, 9);
        state.cards.last_mut().expect("pushed").upgraded = upgraded;
        let _ = dispatch(&mut state, card, Some(enemy));
        state.player.powers.iter().find_map(|pu| {
            state
                .powers
                .iter()
                .find(|p| p.id == pu.0 && p.kind == kind)
                .map(|p| p.amount)
        })
    };
    for (card, kind, base, up) in [
        (CardId::Patter, PowerKind::Vigor, 2, 3),
        (CardId::Resonance, PowerKind::Strength, 1, 2),
        (CardId::PillarOfCreation, PowerKind::PillarOfCreation, 3, 4),
        (CardId::Furnace, PowerKind::Furnace, 5, 7),
        (CardId::ChildOfTheStars, PowerKind::ChildOfTheStars, 2, 3),
        (CardId::BlackHole, PowerKind::BlackHole, 3, 4),
        (CardId::PaleBlueDot, PowerKind::PaleBlueDot, 1, 2),
        (CardId::ParryCard, PowerKind::Parry, 10, 14),
        // sts2-rs-rjnca: upgrade-scaling power amounts.
        (
            CardId::ForegoneConclusion,
            PowerKind::ForegoneConclusion,
            2,
            3,
        ),
        (CardId::Genesis, PowerKind::Genesis, 2, 3),
        (CardId::NeutronAegis, PowerKind::Plating, 8, 11),
        (CardId::Terraforming, PowerKind::Vigor, 6, 8),
    ] {
        assert_eq!(player_power(card, kind, false), Some(base), "{kind:?} base");
        assert_eq!(
            player_power(card, kind, true),
            Some(up),
            "{kind:?} upgraded"
        );
    }
}

