/// Bead `sts2-rs-f7iif` (updated, sweep RP72): Quasar generates 3
/// distinct colorless cards and opens a single-pick skippable
/// `AddGeneratedToHand` choose-a-card screen (C# `GetDistinctForCombat(
/// pool, 3)` → `FromChooseACardScreen(canSkip: true)` →
/// `AddGeneratedCardToCombat(.., Hand)`, no `SetToFreeThisTurn`). Only the
/// chosen id materialises once the choice resolves — same surfacing
/// migration Discovery did under `sts2-rs-y9hvo`. The prior
/// deterministic-first approximation auto-picked the shuffle's first card
/// and never paused, desyncing the harness's `card_select` replay (RP72).
#[test]
fn quasar_generates_three_opens_choose_a_card() {
    install_pool();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    let hand_before = state.player.hand.len();
    let _ = push_play_card(&mut state, CardId::Quasar, 0, 0);
    let _ = dispatch(&mut state, CardId::Quasar, None);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("Quasar opens a choose-a-card screen");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddGeneratedToHand);
    assert_eq!((pc.min_select, pc.max_select), (1, 1), "single pick");
    assert!(pc.can_skip, "C# FromChooseACardScreen(canSkip: true)");
    assert_eq!(pc.options.len(), 3, "GetDistinctForCombat(pool, 3)");
    // No card materialises into hand before the choice resolves — only the
    // chosen id is spawned by the resolver.
    assert_eq!(state.player.hand.len(), hand_before);
    assert_eq!(state.player.generated_cards_this_combat, 0);
}

/// Bead `sts2-rs-qz6v3`: card_star_cost is the source of truth for
/// per-CardId star_cost lookup. Pins the COMPLETE 21-card C#
/// `CanonicalStarCost` table (v0.103.2) — the prior 7-card subset
/// under-counted CrescentSpear's star-card multiplier.
#[test]
fn card_star_cost_pins_regent_table() {
    assert_eq!(card_star_cost(CardId::SevenStars), 7);
    assert_eq!(card_star_cost(CardId::DecisionsDecisions), 6);
    for c in [CardId::Comet, CardId::NeutronAegis, CardId::RoyalGamble] {
        assert_eq!(card_star_cost(c), 5, "{c:?}");
    }
    for c in [CardId::Devastate, CardId::TheSmith] {
        assert_eq!(card_star_cost(c), 4, "{c:?}");
    }
    for c in [
        CardId::Alignment,
        CardId::AstralPulse,
        CardId::DyingStar,
        CardId::GammaBlast,
        CardId::ReflectCard,
        CardId::Resonance,
        CardId::TheSealedThrone,
    ] {
        assert_eq!(card_star_cost(c), 3, "{c:?}");
    }
    for c in [
        CardId::FallingStar,
        CardId::GuidingStar,
        CardId::MeteorShower,
        CardId::ParticleWall,
        CardId::Quasar,
    ] {
        assert_eq!(card_star_cost(c), 2, "{c:?}");
    }
    for c in [CardId::CloakOfStars, CardId::CrescentSpear] {
        assert_eq!(card_star_cost(c), 1, "{c:?}");
    }
    // Non-star-cost cards default to 0.
    assert_eq!(card_star_cost(CardId::StrikeRegent), 0);
    assert_eq!(card_star_cost(CardId::DefendRegent), 0);
    // Stardust is special-cased at the call site (counted as
    // star-cost-bearing) but its own star_cost is still 0.
    assert_eq!(card_star_cost(CardId::Stardust), 0);
}

/// Bead `sts2-rs-qz6v3`: CrescentSpear damage scales by
/// `extra_damage * star_cost_count` over the player's 5 deck
/// piles. Mirrors Python pin `regent.py:L152-L166`. Counts
/// every (uid → card) hit across hand/draw/discard/play/exhaust,
/// so a card present in two piles (e.g. via `push_play_card`
/// dropping it in `play` and the test also placing it in `draw`)
/// is counted twice — matching Python's `_all_cards_for_creature`
/// semantics on a chained iterator.
#[test]
fn crescent_spear_scales_with_star_cost_count() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    // Helper `push_play_card` puts each card into `player.play`;
    // we additionally place each into a distinct deck pile so the
    // multi-pile walk visits both copies of the uid (the player's
    // 5 piles share uid space). Counted occurrences (Python
    // matches this — its chain visits the same instance once per
    // pile membership):
    //   FallingStar (sc=2): play + draw    → 2
    //   AstralPulse (sc=3): play + discard → 2
    //   Stardust    (sc=0 special-cased):  play + exhaust → 2
    //   CrescentSpear (sc=1, counts itself): play only → 1
    // Total count = 7 → damage = 6 (base) + 2 (extra) * 7 = 20.
    // (C# `AllCards.Count(CanonicalStarCost >= 0)` includes the resolving
    // CrescentSpear, which has CanonicalStarCost 1 — bead `sts2-rs-qz6v3`.)
    let fs = push_play_card(&mut state, CardId::FallingStar, 0, 0);
    let ap = push_play_card(&mut state, CardId::AstralPulse, 0, 0);
    let sd = push_play_card(&mut state, CardId::Stardust, 0, 0);
    state.player.draw.push(fs);
    state.player.discard.push(ap);
    state.player.exhaust.push(sd);
    let _ = push_play_card(&mut state, CardId::CrescentSpear, 6, 0);
    let hp0 = state.creatures[0].current_hp;
    let _ = dispatch(&mut state, CardId::CrescentSpear, Some(enemy));
    let dmg = hp0 - state.creatures[0].current_hp;
    assert_eq!(dmg, 6 + CRESCENT_SPEAR_EXTRA_DAMAGE * 7);
}

