fn fresh_state_with_two_enemies(hp_a: i32, hp_b: i32) -> (CombatState, CreatureUid, CreatureUid) {
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    state.player.current_hp = 80;
    state.player.max_hp = 80;
    for (i, hp) in [hp_a, hp_b].iter().enumerate() {
        let id = NonZeroU32::new(u32::try_from(i + 1).expect("fits")).expect("non-zero");
        state.creatures.push(Creature {
            id,
            current_hp: *hp,
            max_hp: *hp,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(id));
    }
    let a = state.enemy_uids[0];
    let b = state.enemy_uids[1];
    (state, a, b)
}

/// Has the player accumulated a power of the given kind?
///
/// Bead `sts2-rs-4zxc0`: post-au4l2 (commit 62d8c3ff) card-driven
/// applies route through `state.creatures[player_uid].powers`
/// instead of the legacy `state.player.powers`. Read from both
/// surfaces so this helper survives both pre- and post-au4l2
/// attachment paths until a canonical `player_powers_iter`
/// accessor lands on CombatState.
fn player_has_power(state: &CombatState, kind: PowerKind) -> Option<i32> {
    let from_legacy = state.player.powers.iter().find_map(|uid| {
        state
            .powers
            .iter()
            .find(|p| p.id == uid.0 && p.kind == kind)
            .map(|p| p.amount)
    });
    if from_legacy.is_some() {
        return from_legacy;
    }
    let creature_uid = state.player.creature_uid?;
    let creature = state.creatures.iter().find(|c| c.id == creature_uid.0)?;
    creature.powers.iter().find_map(|uid| {
        state
            .powers
            .iter()
            .find(|p| p.id == uid.0 && p.kind == kind)
            .map(|p| p.amount)
    })
}

/// AstralPulse: hits every alive enemy for base damage TWICE (C#
/// `.WithHitCount(2)`, v0.107.1) — 4 × 2 = 8 per enemy.
#[test]
fn astral_pulse_hits_every_enemy() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(50, 50);
    let _ = push_play_card(&mut state, CardId::AstralPulse, 4, 0);
    let _ = dispatch(&mut state, CardId::AstralPulse, None);
    let hp_a = state
        .creatures
        .iter()
        .find(|c| c.id == a.0)
        .expect("a")
        .current_hp;
    let hp_b = state
        .creatures
        .iter()
        .find(|c| c.id == b.0)
        .expect("b")
        .current_hp;
    assert_eq!(hp_a, 42);
    assert_eq!(hp_b, 42);
}

