/// CrushUnder (bead `sts2-rs-kfaji`, corrected vs `CrushUnder.cs`):
/// AoE damage + CrushUnder 1 (StrengthLoss=1) on every ENEMY, NOT on
/// the player.
#[test]
fn crush_under_aoes_and_applies_to_enemies() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(30, 30);
    let _ = push_play_card(&mut state, CardId::CrushUnder, 3, 0);
    let _ = dispatch(&mut state, CardId::CrushUnder, None);
    let hp_a = state
        .creatures
        .iter()
        .find(|c| c.id == a.0)
        .expect("a")
        .current_hp;
    let hp_b = state
        .creatures
        .iter()
        .find(|c| c.id == b.0)
        .expect("b")
        .current_hp;
    assert_eq!(hp_a, 27);
    assert_eq!(hp_b, 27);
    // CrushUnder lands on the enemies, not the player.
    assert_eq!(enemy_has_power(&state, a, PowerKind::CrushUnder), Some(1));
    assert_eq!(enemy_has_power(&state, b, PowerKind::CrushUnder), Some(1));
    assert_eq!(player_has_power(&state, PowerKind::CrushUnder), None);
    // sts2-rs-na2z4: TemporaryStrengthPower (IsPositive=false)
    // also folds -1 Strength on each enemy.
    assert_eq!(enemy_has_power(&state, a, PowerKind::Strength), Some(-1));
    assert_eq!(enemy_has_power(&state, b, PowerKind::Strength), Some(-1));
}

/// CrushUnder vs Artifact (bead `sts2-rs-crush-under-artifact`, parity
/// fuzz Regent seed 353): `CrushUnderPower.Type == Debuff`, so an
/// Artifact-warded enemy consumes ONE Artifact stack and negates the
/// whole power — its `BeforeApplied` (the internal silent `-Strength`)
/// never fires. The prior port applied both the Strength rider AND the
/// marker past Artifact (leaving the enemy with 2 extra powers and its
/// Artifact untouched). Damage still lands; an unwarded sibling takes
/// the full CrushUnder + Strength.
#[test]
fn crush_under_debuff_negated_by_enemy_artifact() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(30, 30);
    apply_power_to_enemy(&mut state, a, PowerKind::Artifact, 2);
    let _ = push_play_card(&mut state, CardId::CrushUnder, 3, 0);
    let _ = dispatch(&mut state, CardId::CrushUnder, None);
    // Warded enemy: damage lands, but the CrushUnder debuff + its
    // internal -Strength are negated, consuming exactly one Artifact stack.
    let hp_a = state
        .creatures
        .iter()
        .find(|c| c.id == a.0)
        .unwrap()
        .current_hp;
    assert_eq!(
        hp_a, 27,
        "CrushUnder damage is not a debuff — Artifact never blocks it"
    );
    assert_eq!(enemy_has_power(&state, a, PowerKind::Artifact), Some(1));
    assert_eq!(enemy_has_power(&state, a, PowerKind::CrushUnder), None);
    assert_eq!(enemy_has_power(&state, a, PowerKind::Strength), None);
    // Unwarded sibling takes the full debuff package.
    assert_eq!(enemy_has_power(&state, b, PowerKind::CrushUnder), Some(1));
    assert_eq!(enemy_has_power(&state, b, PowerKind::Strength), Some(-1));
}

/// CrushUnder nets an enemy's Strength to exactly 0 -> PRUNE it (issue
/// #177, parity fuzz Regent seed 868 / TurretOperator). C#
/// `PowerCmd.cs:248-251`: after every amount change, an `AllowNegative`
/// attribute power (Strength) at exactly 0 is removed
/// (`PowerModel.ShouldRemoveDueToAmount`, `PowerModel.cs:480-491`).
/// TurretOperator's ReloadMove gave it +1 Strength; CrushUnder's internal
/// `TemporaryStrengthPower` fold of -1 nets to 0, which C# removes —
/// leaving only the CrushUnder marker. The prior Regent-local helper left
/// a 0-amount Strength lingering (`powers.len` 2 vs C# 1).
#[test]
fn crush_under_prunes_strength_netted_to_zero() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(30, 30);
    // Enemy `a` already carries +1 Strength (e.g. TurretOperator ReloadMove);
    // enemy `b` carries +2 Strength.
    apply_power_to_enemy(&mut state, a, PowerKind::Strength, 1);
    apply_power_to_enemy(&mut state, b, PowerKind::Strength, 2);
    let _ = push_play_card(&mut state, CardId::CrushUnder, 3, 0);
    let _ = dispatch(&mut state, CardId::CrushUnder, None);
    // `a`: +1 - 1 = 0 -> Strength instance pruned, only CrushUnder remains.
    assert_eq!(enemy_has_power(&state, a, PowerKind::CrushUnder), Some(1));
    assert_eq!(
        enemy_has_power(&state, a, PowerKind::Strength),
        None,
        "Strength netted to 0 must be pruned, not left as a 0-amount instance"
    );
    // No stale 0-amount Strength power lingers in the pool either.
    assert!(
        !state
            .powers
            .iter()
            .any(|p| p.kind == PowerKind::Strength && p.amount == 0),
        "no 0-amount Strength power may remain anywhere"
    );
    // `b`: +2 - 1 = +1 -> Strength stays, not pruned.
    assert_eq!(enemy_has_power(&state, b, PowerKind::CrushUnder), Some(1));
    assert_eq!(enemy_has_power(&state, b, PowerKind::Strength), Some(1));
}

/// CrushUnder debuffs only the PRE-attack enemy snapshot (Regent-3001 act3
/// parity). C# `CrushUnder.OnPlay` captures `HittableEnemies` (a `ToList()`
/// copy) before `DamageCmd.Attack`; the Axebot that `StockPower.AfterDeath`
/// spawns mid-attack is not in it, so the replacement carries only its
/// `Stock 1` — no CrushUnder, no -Strength. Rust re-read `enemy_uids` after
/// the damage and debuffed the replacement.
#[test]
fn crush_under_skips_enemy_spawned_by_stock_mid_attack() {
    install_pool();
    crate::cards::dispatch::ensure_installed();
    // `push_play_card(.., 3, ..)` hits for 3: the Axebot at 3 HP dies.
    let (mut state, a, b) = fresh_state_with_two_enemies(3, 30);
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == a.0) {
        c.species = Some(MonsterKind::Axebot);
        c.monster_id = MonsterId("Axebot");
    }
    apply_power_to_enemy(&mut state, a, PowerKind::Stock, 2);
    let _ = push_play_card(&mut state, CardId::CrushUnder, 3, 0);
    let _ = dispatch(&mut state, CardId::CrushUnder, None);

    let spawned: Vec<CreatureUid> = state
        .enemy_uids
        .iter()
        .copied()
        .filter(|u| *u != a && *u != b)
        .filter(|u| {
            state
                .creatures
                .iter()
                .any(|c| c.id == u.0 && c.current_hp > 0)
        })
        .collect();
    assert_eq!(spawned.len(), 1, "Stock respawned exactly one Axebot");
    let new_bot = spawned[0];
    assert_eq!(enemy_has_power(&state, new_bot, PowerKind::Stock), Some(1));
    assert_eq!(
        enemy_has_power(&state, new_bot, PowerKind::CrushUnder),
        None,
        "the mid-attack spawn is not in C#'s HittableEnemies snapshot"
    );
    assert_eq!(enemy_has_power(&state, new_bot, PowerKind::Strength), None);
    // The surviving sibling still takes the full debuff package.
    assert_eq!(enemy_has_power(&state, b, PowerKind::CrushUnder), Some(1));
    assert_eq!(enemy_has_power(&state, b, PowerKind::Strength), Some(-1));
}

/// MonarchsGaze powered-attack StrengthDown vs Artifact (bead
/// `sts2-rs-hhjfb`, parity fuzz Regent seed 136 / CHOMPER): the player's
/// `MonarchsGazePower.AfterDamageGiven` applies a `MonarchsGazeStrengthDown`
/// (a Debuff) to each powered-attack target. An Artifact-warded target
/// consumes ONE Artifact stack and negates the WHOLE application — its
/// `BeforeApplied` (the silent internal `-Strength`) never fires. The prior
/// port folded the `-Strength` past Artifact (leaving the enemy with a
/// leaked `STRENGTH -1` while Artifact absorbed only the marker). Damage
/// still lands; an unwarded sibling takes the full StrengthDown package.
#[test]
fn monarchs_gaze_strength_down_negated_by_enemy_artifact() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(80, 80);
    apply_power_to_enemy(&mut state, a, PowerKind::Artifact, 2);
    apply_power_to_player(&mut state, PowerKind::MonarchsGaze, 1);
    // Powered attack into the warded enemy: damage lands, but the
    // StrengthDown marker + its internal -Strength are negated, consuming
    // exactly one Artifact stack.
    let uid_a = push_play_card(&mut state, CardId::ShiningStrike, 6, 0);
    let _ = uid_a;
    let _ = dispatch(&mut state, CardId::ShiningStrike, Some(a));
    assert_eq!(enemy_has_power(&state, a, PowerKind::Artifact), Some(1));
    assert_eq!(
        enemy_has_power(&state, a, PowerKind::MonarchsGazeStrengthDown),
        None
    );
    assert_eq!(
        enemy_has_power(&state, a, PowerKind::Strength),
        None,
        "Artifact-absorbed StrengthDown must NOT leak -Strength onto the target"
    );
    // Powered attack into the unwarded sibling: full StrengthDown package
    // (marker + folded -1 Strength).
    let _ = push_play_card(&mut state, CardId::ShiningStrike, 6, 0);
    let _ = dispatch(&mut state, CardId::ShiningStrike, Some(b));
    assert_eq!(
        enemy_has_power(&state, b, PowerKind::MonarchsGazeStrengthDown),
        Some(1)
    );
    assert_eq!(enemy_has_power(&state, b, PowerKind::Strength), Some(-1));
}

/// C# `CreatureCmd.Damage` runs `Hook.AfterDamageGiven` BEFORE
/// `Hook.AfterDamageReceived` (CreatureCmd.cs:388-395): MonarchsGaze's
/// StrengthDown lands first, then the Ceremonial Beast's
/// `PlowPower.AfterDamageReceived` strips the TemporaryStrength family
/// (StrengthDown included), Strength and Plow — the beast ends with no
/// powers (loadout Regent v0.107.1 2014; Rust ran received first and left
/// `[STRENGTH -1, MONARCHS_GAZE_STRENGTH_DOWN 1]`).
#[test]
fn plow_break_strips_the_monarchs_gaze_strength_down_of_the_same_hit() {
    install_pool();
    let (mut state, e) = fresh_state_with_enemy(160);
    {
        let beast = state
            .creatures
            .iter_mut()
            .find(|c| c.id == e.0)
            .expect("beast");
        beast.species = Some(MonsterKind::CeremonialBeast);
        beast.monster_id = MonsterId("CeremonialBeast");
        let mut ai = crate::monsters::act1_overgrowth::create_ceremonial_beast_ai();
        ai.set_owner(e);
        beast.ai = Some(ai);
    }
    apply_power_to_enemy(&mut state, e, PowerKind::Plow, 150);
    apply_power_to_enemy(&mut state, e, PowerKind::Strength, 4);
    apply_power_to_player(&mut state, PowerKind::MonarchsGaze, 1);
    let _ = push_play_card(&mut state, CardId::ShiningStrike, 20, 0);
    let _ = dispatch(&mut state, CardId::ShiningStrike, Some(e));
    let beast = state.creatures.iter().find(|c| c.id == e.0).expect("beast");
    assert_eq!(beast.current_hp, 140);
    assert!(
        beast.powers.is_empty(),
        "Plow's break stripped everything, StrengthDown included: {:?}",
        beast
            .powers
            .iter()
            .filter_map(|p| state.powers.get_by_id(p.0).map(|p| (p.kind, p.amount)))
            .collect::<Vec<_>>()
    );
}

