/// Glow: 1 Star + draws 2 cards from the draw pile.
#[test]
fn glow_gains_one_star_draws_one_and_arms_next_turn_draw() {
    // C# Glow.cs (bead `sts2-rs-tc2ah`): gain Stars=1 base, draw
    // Cards=1, apply DrawCardsNextTurn(Cards=1). The pre-fix
    // assertion encoded the Python-pin port bug (draw 2 + no next-
    // turn rider).
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let pad1 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    let pad2 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    state.player.play.clear();
    state.player.draw.push(pad1);
    state.player.draw.push(pad2);
    let hand_before = state.player.hand.len();
    let _ = push_play_card(&mut state, CardId::Glow, 0, 0);
    let _ = dispatch(&mut state, CardId::Glow, None);
    assert_eq!(state.player.stars, 1);
    assert_eq!(state.player.hand.len() - hand_before, 1);
    // DrawCardsNextTurn(1) was applied to the player.
    let dnt_amount = state.player.powers.iter().find_map(|uid| {
        state
            .powers
            .iter()
            .find(|p| p.id == uid.0 && p.kind == PowerKind::DrawCardsNextTurn)
            .map(|p| p.amount)
    });
    assert_eq!(dnt_amount, Some(1));
}

