// Glimmer (sts2-rs-yc2d): after drawing 3, opens a `PutBack`
// pending choice over the resulting hand. Each option carries the
// hand-pile uid + source_pile so the dispatch trampoline can
// resolve via `resolve_putback_choice`.

/// PhotonCut (bead `sts2-rs-k2gai`, yc2d glimmer-mirror): damage +
/// draw 1 + PutBack choice over the post-draw hand. Pins all
/// three legs together so a future regression to the choice arm
/// is caught alongside the damage/draw legs.
#[test]
fn photon_cut_damages_draws_and_opens_putback_choice() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    let p1 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    let p2 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    state.player.play.clear();
    state.player.draw.extend([p1, p2]);
    // A second hand card, so the put-back is a real choice (a lone card goes
    // back without one, CardSelectCmd.cs:713).
    let _ = push_hand_card(&mut state, CardId::StrikeRegent);
    let _ = push_play_card(&mut state, CardId::PhotonCut, 5, 0);
    let hp0 = state.creatures[0].current_hp;
    let _ = dispatch(&mut state, CardId::PhotonCut, Some(enemy));
    assert_eq!(hp0 - state.creatures[0].current_hp, 5);
    assert!(!state.player.hand.is_empty());
    let pc = state
        .pending_choice
        .as_ref()
        .expect("PhotonCut must open a pending card-choice");
    assert_eq!(pc.kind, ChoiceKind::PutBack);
    assert_eq!(pc.options.len(), state.player.hand.len());
    assert!(!pc.can_skip, "PhotonCut choice is not skippable");
    assert_eq!((pc.min_select, pc.max_select), (1, 1));
    for opt in &pc.options {
        assert!(opt.card_uid.is_some(), "options must carry hand uids");
        assert_eq!(opt.source_pile, Some(sts2_core::cards::PileKind::Hand));
    }
}

/// PhotonCut with empty post-draw hand (e.g. empty draw pile)
