/// Resolving Glimmer's choice via the engine `apply` trampoline
/// moves the chosen hand card to top-of-draw and clears the
/// pending choice.
#[test]
fn glimmer_resolve_choice_moves_card_to_top_of_draw() {
    use sts2_core::{apply, Action};
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let p1 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    let p2 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    let p3 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    state.player.play.clear();
    state.player.draw.extend([p1, p2, p3]);
    let _ = push_play_card(&mut state, CardId::Glimmer, 0, 0);
    let _ = dispatch(&mut state, CardId::Glimmer, None);
    // Pick the first hand option.
    let chosen_uid = state.pending_choice.as_ref().expect("choice open").options[0]
        .card_uid
        .expect("uid present");
    let mut sel: SmallVec<[u8; 4]> = SmallVec::new();
    sel.push(0);
    let _ = apply(&mut state, Action::ResolveChoice { selection: sel });
    assert!(state.pending_choice.is_none(), "choice cleared on resolve");
    assert_eq!(
        state.player.draw.first().copied(),
        Some(chosen_uid),
        "chosen card on top of draw"
    );
    assert!(
        !state.player.hand.contains(&chosen_uid),
        "chosen card removed from hand"
    );
}

/// `request_card_choice` honors `can_skip=true` by enumerating
/// an empty-selection ResolveChoice in `legal_actions`, and
/// applying the empty selection clears the choice as a no-op
/// (no card moves). Direct on `CombatState::request_card_choice`
/// so the test exercises the primitive independently of any
/// specific Regent card body.
#[test]
fn request_card_choice_skip_path_is_noop() {
    use sts2_core::{apply, legal_actions, Action};
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    // Seed a single hand card so we have a non-empty option set.
    let h1 = push_play_card(&mut state, CardId::Venerate, 0, 0);
    state.player.play.clear();
    state.player.hand.push(h1);
    let card = &state.cards[h1.0.get() as usize - 1];
    let opts = vec![ChoiceOption {
        card_id: card.card_id,
        upgraded: card.upgraded,
        card_uid: Some(h1),
        source_pile: Some(sts2_core::cards::PileKind::Hand),
    }];
    state.request_card_choice(ChoiceKind::PutBack, opts, 0, 1, true);
    let acts = legal_actions(&state);
    // Expect: 1 single-pick action + 1 empty-selection skip.
    let has_skip = acts
        .iter()
        .any(|a| matches!(a, Action::ResolveChoice { selection } if selection.is_empty()));
    assert!(has_skip, "skip action must be enumerated when can_skip");
    let draw_before = state.player.draw.clone();
    let hand_before = state.player.hand.clone();
    let _ = apply(
        &mut state,
        Action::ResolveChoice {
            selection: SmallVec::new(),
        },
    );
    assert!(state.pending_choice.is_none(), "choice cleared on skip");
    assert_eq!(state.player.draw, draw_before, "draw unchanged on skip");
    assert_eq!(state.player.hand, hand_before, "hand unchanged on skip");
}

/// `request_card_choice` is a no-op when `options` is empty (Python
/// callers short-circuit before opening; the Rust primitive
/// mirrors that defensively so callers don't have to repeat the
/// guard).
#[test]
fn request_card_choice_empty_options_no_choice_opened() {
    let mut state = CombatState::default();
    state.request_card_choice(ChoiceKind::PutBack, Vec::new(), 1, 1, false);
    assert!(state.pending_choice.is_none());
}

