/// Resonance's `-1 Strength` that drives an enemy's existing Strength to
/// exactly 0 must REMOVE the power row, not leave a `Strength@0`. C#
/// `StrengthPower.AllowNegative => true`, so `ShouldRemoveDueToAmount`
/// returns `Amount == 0` (PowerModel.cs:480-491) and the stacking
/// `PowerCmd.Apply<StrengthPower>` nulls the power when `ModifyAmount == 0`
/// (PowerCmd.cs:84-86 → ModifyAmount Remove at :248-250). Live divergence:
/// Regent parity seed 3843 (MONSTER_STATE|RESONANCE) — monsters[0] carried
/// +1 Strength; Resonance's -1 drove it to 0, C# removed the row (0 powers)
/// while Rust left a Strength@0 (1 power). The prune lives in the shared
/// Regent helper `add_power_to_enemy_signed` (fixed alongside CrushUnder).
#[test]
fn resonance_drain_to_zero_removes_enemy_strength() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(50, 50);
    // Enemy `a` pre-carries +1 Strength → Resonance's -1 lands it at 0.
    apply_power_to_enemy(&mut state, a, PowerKind::Strength, 1);
    // Enemy `b` pre-carries +2 Strength → -1 keeps a non-zero (+1) row.
    apply_power_to_enemy(&mut state, b, PowerKind::Strength, 2);
    let _ = push_play_card(&mut state, CardId::Resonance, 0, 0);
    let _ = dispatch(&mut state, CardId::Resonance, None);
    assert_eq!(player_has_power(&state, PowerKind::Strength), Some(1));
    // Driven to exactly 0 → pruned (mirrors C# ShouldRemoveDueToAmount).
    assert_eq!(enemy_has_power(&state, a, PowerKind::Strength), None);
    // Non-zero result keeps the row.
    assert_eq!(enemy_has_power(&state, b, PowerKind::Strength), Some(1));
}

/// Resonance vs Artifact (bead `sts2-rs-crush-under-artifact`, parity
/// fuzz Regent seed 306): C# applies `-1 Strength` to each enemy via
/// `PowerCmd.Apply<StrengthPower>(enemy, -1)`, a debuff-direction drain
/// that Artifact negates (consuming one stack). The prior port pushed the
/// drain through the non-Artifact-aware signed helper, so a warded enemy
/// kept both its Strength and its Artifact. The self +Strength is a buff
/// and is never gated.
#[test]
fn resonance_strength_drain_negated_by_enemy_artifact() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(50, 50);
    apply_power_to_enemy(&mut state, a, PowerKind::Artifact, 1);
    let _ = push_play_card(&mut state, CardId::Resonance, 0, 0);
    let _ = dispatch(&mut state, CardId::Resonance, None);
    assert_eq!(player_has_power(&state, PowerKind::Strength), Some(1));
    // Warded enemy: drain negated, one Artifact stack consumed.
    assert_eq!(enemy_has_power(&state, a, PowerKind::Artifact), None);
    assert_eq!(enemy_has_power(&state, a, PowerKind::Strength), None);
    // Unwarded sibling takes the full -1 Strength.
    assert_eq!(enemy_has_power(&state, b, PowerKind::Strength), Some(-1));
}

