/// ShiningStrike: damage + 2 Stars + reinsert resolving card on
/// top of draw pile (`!exhausts` arm). Bead `sts2-rs-a649q`
/// extends the damage+stars test to assert the grne-follow-up
/// reinsert: post-dispatch the ShiningStrike uid lives at the
/// HEAD of `state.player.draw` (not in the play pile, not in
/// discard, not in exhaust).
#[test]
fn shining_strike_damages_and_stars() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    let uid = push_play_card(&mut state, CardId::ShiningStrike, 6, 0);
    let hp0 = state.creatures[0].current_hp;
    assert!(
        state.player.play.last().copied() == Some(uid),
        "fixture: ShiningStrike uid must be on the play pile pre-dispatch",
    );
    let _ = dispatch(&mut state, CardId::ShiningStrike, Some(enemy));
    assert_eq!(hp0 - state.creatures[0].current_hp, 6);
    assert_eq!(state.player.stars, 2);
    // The reinsert-to-draw-top leg now runs in the `play_card`
    // play-finish epilogue (so the card stays resolvable across
    // OneTwoPunch / EchoForm replays), NOT in the handler. A direct
    // `dispatch` therefore leaves the card on the Play pile — the
    // engine's single move-out-of-Play step routes it to draw top.
    assert!(
        state.player.play.contains(&uid),
        "ShiningStrike uid stays on the play pile post-dispatch (reinsert deferred to epilogue)",
    );
}

