/// `BeatIntoShape`: 2 prior powered hits to THE TARGET → forge 5 + 2*5 = 15.
/// Bead `sts2-rs-o51u`. The prior hits are landed as real powered
/// player→target hits so they populate the per-target tally that
/// `BeatIntoShape`'s forge multiplier reads (issue #177 made the read
/// strictly per-target, matching C# `BeatIntoShape.cs:27-31`'s
/// `e.Receiver == target` filter).
#[test]
fn beat_into_shape_forge_scales_with_prior_hits() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    // Land 2 prior powered hits ON THE SAME ENEMY this turn so the
    // per-target tally for `enemy` is 2.
    for _ in 0..2 {
        let _ = sts2_core::damage::apply_damage(
            &mut state,
            CreatureRef::Player,
            enemy,
            1,
            sts2_core::hooks::ValueProps::MOVE,
            None,
        );
    }
    assert_eq!(
        state.count_player_powered_hits_on_target_this_turn(enemy),
        2,
        "two prior powered hits on the target",
    );
    let _ = push_play_card(&mut state, CardId::BeatIntoShape, 8, 0);
    let dmg_before = sovereign_blade_total_damage(&state);
    let _ = dispatch(&mut state, CardId::BeatIntoShape, Some(enemy));
    // Forge 15 with no prior blade: spawns 1 (base 10) + buff 15 = +25.
    assert_eq!(
        sovereign_blade_total_damage(&state) - dmg_before,
        25,
        "Forge 5 + 2 × 5 = 15: spawn 1 blade (base 10) + buff 15"
    );
}

/// `BeatIntoShape` multi-enemy regression (issue #177): the forge
/// multiplier is STRICTLY per-target. C# `BeatIntoShape.cs:27-31` counts
/// `DamageReceivedEntry`s with `e.Receiver == target`, so powered hits
/// the player landed on enemy A this turn must NOT inflate a
/// BeatIntoShape played on enemy B. Before the fix the Rust port read a
/// combat-wide scalar (`count_player_powered_hits_this_turn`), so 2
/// prior hits on A wrongly forged 5 + 2×5 = 15 on B (+25 blade damage)
/// instead of the correct floor 5 (+15).
#[test]
fn beat_into_shape_forge_is_per_target_not_combat_wide() {
    install_pool();
    let (mut state, a, b) = fresh_state_with_two_enemies(200, 200);
    // Land 2 powered hits on enemy A this turn.
    for _ in 0..2 {
        let _ = sts2_core::damage::apply_damage(
            &mut state,
            CreatureRef::Player,
            a,
            1,
            sts2_core::hooks::ValueProps::MOVE,
            None,
        );
    }
    assert_eq!(
        state.count_player_powered_hits_on_target_this_turn(a),
        2,
        "A has 2 prior powered hits",
    );
    assert_eq!(
        state.count_player_powered_hits_on_target_this_turn(b),
        0,
        "B has none",
    );
    // Play BeatIntoShape targeting enemy B — its forge must see 0 prior
    // hits on B, NOT the 2 hits on A.
    let _ = push_play_card(&mut state, CardId::BeatIntoShape, 8, 0);
    let dmg_before = sovereign_blade_total_damage(&state);
    let _ = dispatch(&mut state, CardId::BeatIntoShape, Some(b));
    assert_eq!(
        sovereign_blade_total_damage(&state) - dmg_before,
        15,
        "per-target: forge 5 (floor) on B → +15, NOT 15-forge (+25) \
         leaking A's hits",
    );
}

/// `BeatIntoShape` companion (issue #177): per-target hits DO count when
/// the prior hit was on the SAME enemy, and the card's own just-landed
/// hit is excluded (C# `BeatIntoShape.cs:48-49` subtracts this attack's
/// hit count). 1 prior hit on the target → forge per + per×1 = 10.
#[test]
fn beat_into_shape_same_target_hits_count_and_self_excluded() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    // One prior powered hit on the target this turn.
    let _ = sts2_core::damage::apply_damage(
        &mut state,
        CreatureRef::Player,
        enemy,
        1,
        sts2_core::hooks::ValueProps::MOVE,
        None,
    );
    let _ = push_play_card(&mut state, CardId::BeatIntoShape, 8, 0);
    let dmg_before = sovereign_blade_total_damage(&state);
    let _ = dispatch(&mut state, CardId::BeatIntoShape, Some(enemy));
    // prior_hits captured BEFORE the attack leg = 1 (its own hit
    // excluded). Forge 5 + 1×5 = 10: spawn 1 blade (base 10) + buff 10.
    assert_eq!(
        sovereign_blade_total_damage(&state) - dmg_before,
        20,
        "same-target: forge 5 + 1×5 = 10 (own hit excluded) → +20",
    );
}

