/// Bombardment `AfterAutoPrePlayPhaseEnteredEarly` rider: while it sits in the
/// owner's Exhaust pile it auto-plays itself every turn start, dealing 18 to a
/// random enemy (rolled off the `combat_targets` stream) and re-exhausting via
/// its Exhaust keyword. Mirrors C# `Bombardment.cs:46-54`
/// (`if pile?.Type == Exhaust && player == Owner -> CardCmd.AutoPlay(this)`).
/// Without the rider Rust skipped the recurring damage AND the per-turn
/// `combat_targets` read (Regent coverage seed 7: monsters[1].hp cs=37 rs=55,
/// combat_targets cs=1 rs=0). Bead `sts2-rs-bombardment-handraw`. The auto-play
/// fires in the AutoPrePlay phase (after the hand draw + side-turn-start, bead
/// `sts2-rs-bombardment-autoprePlay`); this end-state assertion is phase-agnostic
/// (no-block enemy), the ordering is pinned by
/// `bombardment_follows_rampart_block` below.
#[test]
fn bombardment_auto_plays_from_exhaust_at_turn_start() {
    crate::cards::dispatch::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(200);
    // Faithful Bombardment card (base 18, EXHAUST via the CardId registry),
    // resting in the exhaust pile as if a prior play had exhausted it.
    let bomb = {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: CardId::Bombardment,
            cost: 3,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 18,
            base_block: 0,
            combat_vars: sts2_core::cards::CombatVars::new(),
            enchantments: sts2_core::cards::CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        state.player.exhaust.push(uid);
        uid
    };
    state.phase = sts2_core::CombatPhase::PlayerTurnStart;
    state.round = 2;
    let hp0 = state.creatures[0].current_hp;
    let targets_before = state.run_rng.combat_targets.counter();

    let _ = sts2_core::combat_loop::start_player_turn(&mut state);

    assert_eq!(
        hp0 - state.creatures[0].current_hp,
        18,
        "exhaust-pile Bombardment auto-plays for 18 at hand draw"
    );
    assert!(
        state.player.exhaust.contains(&bomb),
        "Bombardment re-exhausts (Exhaust keyword) and recurs next turn"
    );
    assert_eq!(
        state.run_rng.combat_targets.counter(),
        targets_before + 1,
        "the auto-play rolls exactly one random-enemy target off combat_targets"
    );
}

/// Bombardment's exhaust-pile auto-play fires in the AutoPrePlay phase, which
/// C# `CombatManager` runs AFTER the outer-loop `Hook.AfterSideTurnStart`
/// (`:570` follows `:524`). So an enemy's turn-start block (RampartPower's 25,
/// granted in `after_side_turn_start`) is LIVE when Bombardment's 18 lands —
/// the damage is absorbed by the shield, leaving HP untouched. Bead
/// `sts2-rs-bombardment-autoprePlay` (#177): the prior placement fired the scan
/// pre-hand-draw in `continue_player_turn_setup`, BEFORE Rampart armed the
/// block, so the 18 hit bare HP (Regent TURRET_OPERATOR seed 3940 block-bypass).
/// A single TurretOperator carrying its own Rampart(25) is the only enemy, so
/// the random `AnyEnemy` target is deterministic.
#[test]
fn bombardment_follows_rampart_block() {
    crate::cards::dispatch::install_default_registry();
    let mut state = CombatState {
        rng: sts2_core::dotnet_rng::Rng::new(0_i32),
        ..Default::default()
    };
    state.player.current_hp = 80;
    state.player.max_hp = 80;

    // Single TurretOperator (uid 1) carrying its OWN Rampart(25): on every
    // PLAYER turn-start its `after_side_turn_start` re-grants 25 retained block
    // to each living TurretOperator (here, itself). 41 HP, 0 block at rest.
    let rampart_pid = NonZeroU32::new(1).expect("non-zero");
    state.powers.push(sts2_core::Power {
        id: rampart_pid,
        kind: sts2_core::PowerKind::Rampart,
        amount: 25,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    let turret_id = NonZeroU32::new(1).expect("non-zero");
    state.creatures.push(Creature {
        id: turret_id,
        current_hp: 41,
        max_hp: 41,
        block: 0,
        powers: SmallVec::from_buf_and_len([sts2_core::PowerUid(rampart_pid); 8], 1),
        species: Some(MonsterKind::TurretOperator),
        intent: None,
        intent_history: IntentHistory::default(),
        monster_id: MonsterId("TurretOperator"),
        ai: None,
    });
    state.enemy_uids.push(CreatureUid(turret_id));

    // Faithful Bombardment (base 18, EXHAUST) resting in the exhaust pile.
    let bomb = {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: CardId::Bombardment,
            cost: 3,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 18,
            base_block: 0,
            combat_vars: sts2_core::cards::CombatVars::new(),
            enchantments: sts2_core::cards::CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        state.player.exhaust.push(uid);
        uid
    };
    state.phase = sts2_core::CombatPhase::PlayerTurnStart;
    state.round = 2;

    let _ = sts2_core::combat_loop::start_player_turn(&mut state);

    let turret = state
        .creatures
        .iter()
        .find(|c| c.id == turret_id)
        .expect("turret present");
    assert_eq!(
        turret.current_hp, 41,
        "Bombardment fires AFTER Rampart's turn-start block, so its 18 hits the \
         shield, not bare HP (pre-fix: hp 23)"
    );
    assert_eq!(
        turret.block, 7,
        "25 Rampart block absorbs the 18 Bombardment damage, leaving 7 (pre-fix: \
         block 25, damage already eaten the HP)"
    );
    assert!(
        state.player.exhaust.contains(&bomb),
        "Bombardment re-exhausts via its Exhaust keyword"
    );
}

/// `BundleOfJoy`: spawns 3 distinct colorless modifier cards
/// into hand. Bead `sts2-rs-9oqw` retrofitted from marker-only.
#[test]
fn bundle_of_joy_spawns_three_modifiers_into_hand() {
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let hand_before = state.player.hand.len();
    let _ = push_play_card(&mut state, CardId::BundleOfJoy, 0, 0);
    let r = dispatch(&mut state, CardId::BundleOfJoy, None);
    assert_eq!(r, EffectResult::Resolved);
    assert_eq!(
        state.player.hand.len() - hand_before,
        3,
        "BundleOfJoy spawns exactly 3 cards into hand"
    );
    // Distinct check: the spawned uids should resolve to 3 distinct
    // card_ids (Python `distinct=True` is enforced by the helper).
    let new_uids: SmallVec<[sts2_core::CardUid; 4]> =
        state.player.hand.iter().rev().take(3).copied().collect();
    let mut ids: smallvec::SmallVec<[CardId; 4]> = SmallVec::new();
    for uid in &new_uids {
        let idx = uid.0.get() as usize - 1;
        ids.push(state.cards[idx].card_id);
    }
    ids.sort_by_key(|id| format!("{id:?}"));
    ids.dedup();
    assert_eq!(ids.len(), 3, "all 3 spawned cards have distinct card_ids");
}

