/// `DecisionsDecisions` with 2+ Skill candidates in hand surfaces a
/// single-pick `AutoPlaySkillFromHand` choice (C# `FromHand` count >
/// MinSelect == 1), in hand order, over the Skill cards only.
#[test]
fn decisions_decisions_surfaces_skill_select_with_multiple_skills() {
    crate::cards::dispatch::install_default_registry();
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    // Two Skill candidates (DefendRegent, Venerate) + one Attack (FallingStar)
    // in hand: only the two Skills are options.
    let d = push_hand_skill(&mut state, CardId::DefendRegent);
    let _atk = push_hand_card(&mut state, CardId::FallingStar);
    let v = push_hand_skill(&mut state, CardId::Venerate);
    let _ = push_play_card(&mut state, CardId::DecisionsDecisions, 0, 0);
    let _ = dispatch(&mut state, CardId::DecisionsDecisions, None);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("2+ Skill candidates open a choice");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AutoPlaySkillFromHand);
    assert_eq!(pc.min_select, 1);
    assert_eq!(pc.max_select, 1);
    let uids: Vec<_> = pc.options.iter().filter_map(|o| o.card_uid).collect();
    assert_eq!(uids, vec![d, v], "only the two Skills, in hand order");
    for o in &pc.options {
        assert_eq!(o.source_pile, Some(sts2_core::cards::PileKind::Hand));
    }
}

/// `DecisionsDecisions` resolving the `AutoPlaySkillFromHand` choice
/// auto-plays the chosen Skill 3 times (C# `RepeatVar(3)`), routing it
/// hand → discard across repeats. Picking DefendRegent (5 block,
/// non-Exhaust) yields 15 block: the resolver re-locates the same uid
/// across piles each AutoPlay (hand on the 1st play, discard on 2nd/3rd).
#[test]
fn decisions_decisions_resolves_to_three_auto_plays() {
    crate::cards::dispatch::install_default_registry();
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let d = push_hand_skill(&mut state, CardId::DefendRegent);
    let v = push_hand_skill(&mut state, CardId::Venerate);
    let _ = push_play_card(&mut state, CardId::DecisionsDecisions, 0, 0);
    let _ = dispatch(&mut state, CardId::DecisionsDecisions, None);
    let pc = state.pending_choice.as_ref().expect("choice surfaced");
    // Pick the option that is DefendRegent.
    let pick = pc
        .options
        .iter()
        .position(|o| o.card_uid == Some(d))
        .expect("DefendRegent is an option");
    let block0 = state.player.block;
    let selection: SmallVec<[u8; 4]> = [u8::try_from(pick).expect("fits")].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    // DefendRegent (base 5 block) auto-played 3 times → +15 block. This only
    // holds if the resolver replays the card across hand → discard each repeat.
    assert_eq!(
        state.player.block - block0,
        15,
        "chosen Skill auto-played 3 times (5 block × 3)"
    );
    // Venerate (the unpicked Skill) is untouched in hand.
    assert!(
        state.player.hand.contains(&v),
        "unpicked Skill stays in hand"
    );
}

/// A repeated Skill that opens its OWN select (Quasar's choose-a-card) must
/// resolve it before the next repeat (C# awaits each `CardCmd.AutoPlay`,
/// `DecisionsDecisions.cs:33-36`), and each select prompts the player (GH
/// #1131). The first repeat used to surface, parking Quasar on Play, and
/// repeats 2/3 found it in no pile — 1 generated card instead of 3 (Regent
/// quick seed 452).
#[test]
fn decisions_decisions_repeats_a_selecting_skill_three_times() {
    crate::cards::dispatch::install_default_registry();
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let q = push_hand_skill(&mut state, CardId::Quasar);
    let _v = push_hand_skill(&mut state, CardId::Venerate);
    let _ = push_play_card(&mut state, CardId::DecisionsDecisions, 0, 0);
    let _ = dispatch(&mut state, CardId::DecisionsDecisions, None);
    let pc = state.pending_choice.as_ref().expect("choice surfaced");
    let pick = pc
        .options
        .iter()
        .position(|o| o.card_uid == Some(q))
        .expect("Quasar is an option");
    let gen0 = state.player.generated_cards_this_combat;
    let selection: SmallVec<[u8; 4]> = [u8::try_from(pick).expect("fits")].into_iter().collect();
    let _ = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    for repeat in 1..=3 {
        assert_eq!(
            state.player.generated_cards_this_combat - gen0,
            repeat - 1,
            "repeat {repeat} waits for its pick"
        );
        assert!(
            state.pending_choice.is_some(),
            "repeat {repeat} surfaces Quasar's choose-a-card"
        );
        let selection: SmallVec<[u8; 4]> = [0u8].into_iter().collect();
        let _ = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    }
    assert!(state.pending_choice.is_none());
    assert_eq!(
        state.player.generated_cards_this_combat - gen0,
        3,
        "Quasar auto-played 3 times, one generated card each"
    );
    assert!(
        !state.player.play.contains(&q),
        "Quasar not stranded on Play"
    );
}

/// An AUTO-PLAYED DecisionsDecisions keeps its own tail and its parent's loop
/// waiting across all three repeats: Catastrophe finishes after them, and
/// DecisionsDecisions reaches its result pile before Catastrophe does.
#[test]
fn auto_played_decisions_decisions_waits_for_each_repeat() {
    crate::cards::dispatch::install_default_registry();
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let q = push_hand_skill(&mut state, CardId::Quasar);
    let _v = push_hand_skill(&mut state, CardId::Venerate);
    let decisions = push_hand_skill(&mut state, CardId::DecisionsDecisions);
    state.player.hand.retain(|u| *u != decisions);
    state.player.draw.push(decisions);
    let catastrophe = push_hand_skill(&mut state, CardId::Catastrophe);
    state.cards[catastrophe.get() as usize - 1].cost = 0;
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    state.side = sts2_core::Side::Player;
    let hand_index = u8::try_from(state.player.hand.len() - 1).expect("fits");
    let _ = sts2_core::apply(
        &mut state,
        sts2_core::Action::PlayCard {
            hand_index,
            target: None,
        },
    );
    let pc = state.pending_choice.as_ref().expect("Decisions' pick");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AutoPlaySkillFromHand);
    let pick = pc
        .options
        .iter()
        .position(|o| o.card_uid == Some(q))
        .expect("Quasar is an option");
    let gen0 = state.player.generated_cards_this_combat;
    let selection: SmallVec<[u8; 4]> = [u8::try_from(pick).expect("fits")].into_iter().collect();
    let _ = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    for repeat in 1..=3 {
        assert!(state.pending_choice.is_some(), "repeat {repeat} prompts");
        assert!(state.player.play.contains(&decisions));
        assert!(state.player.play.contains(&catastrophe));
        let selection: SmallVec<[u8; 4]> = [0u8].into_iter().collect();
        let _ = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    }
    assert!(state.pending_choice.is_none());
    assert_eq!(state.player.generated_cards_this_combat - gen0, 3);
    assert!(state.pending_autoplay_resume.is_none());
    assert!(state.pending_play.is_none());
    assert!(!state.player.play.contains(&decisions));
    assert!(!state.player.play.contains(&catastrophe));
}

