/// Guards with a non-empty hand: C# `CardSelectCmd.FromHand(prefs(0, ∞), filter:
/// null)` opens a MULTI-select (min 0, skippable, max = whole hand) transform
/// choice; resolving transforms EACH chosen card into `MinionSacrifice` (the
/// others untouched). Replaces the prior pick-first-card-inline port that
/// desynced whole-run parity vs the C# headless agent (seed PARITY110 A5: C#
/// entered `card_select` at the Guards play, Rust stayed in `combat`). Bead
/// `sts2-rs-guards-select`.
#[test]
fn guards_opens_multi_select_and_transforms_each_chosen_to_minion_sacrifice() {
    crate::cards::dispatch::install_default_registry();
    // The core-side resolver mints MinionSacrifice through the registered card
    // factory (registered by the run/relic-dispatch path in real combat).
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    let (mut state, enemy) = fresh_state_with_enemy(100);
    // Seed three distinct, observable hand cards.
    let a = push_hand_card(&mut state, CardId::StrikeRegent);
    let b = push_hand_card(&mut state, CardId::FallingStar);
    let c = push_hand_card(&mut state, CardId::Venerate);
    let _ = push_play_card(&mut state, CardId::Guards, 0, 0);

    let r = dispatch(&mut state, CardId::Guards, Some(enemy));
    assert_eq!(r, EffectResult::Resolved);
    let pc = state
        .pending_choice
        .as_ref()
        .expect("Guards opens a choice");
    assert_eq!(
        pc.kind,
        sts2_core::ChoiceKind::TransformInHandToMinionSacrifice
    );
    assert_eq!(pc.min_select, 0, "min 0 — skippable");
    assert_eq!(
        pc.options.len(),
        3,
        "whole hand is selectable, in hand order"
    );
    assert_eq!(pc.options[0].card_uid, Some(a));
    assert_eq!(pc.options[1].card_uid, Some(b));
    assert_eq!(pc.options[2].card_uid, Some(c));

    // Select the FIRST and THIRD cards (multi-select) — both transform; `b` stays.
    let selection: SmallVec<[u8; 4]> = [0u8, 2u8].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none(), "choice cleared on resolve");
    assert!(state.player.hand.contains(&b), "unchosen card untouched");
    assert!(
        !state.player.hand.contains(&a),
        "chosen card a slot rebound"
    );
    assert!(
        !state.player.hand.contains(&c),
        "chosen card c slot rebound"
    );
    // `b` is still its original card; the two rebound slots are MinionSacrifice.
    let b_card = &state.cards[b.0.get() as usize - 1];
    assert_eq!(b_card.card_id, CardId::FallingStar, "b unchanged");
    let minions = state
        .player
        .hand
        .iter()
        .filter(|&&u| u != b)
        .filter(|&&u| state.cards[u.0.get() as usize - 1].card_id == CardId::MinionSacrifice)
        .count();
    assert_eq!(minions, 2, "both chosen slots are now MinionSacrifice");
}

