/// `MakeItSo`: late-effect rider returns the watched MakeItSo card to hand
/// from Discard once the count of Skills played this turn is a multiple of
/// `interval`. The count comes from the wire-carried
/// `cards_played_this_turn[Skill]` bucket — C# reads
/// `History.CardPlaysFinished` filtered to this turn's Skills
/// (`MakeItSo.cs:40`) — and the tests drive that bucket for the same reason:
/// the old `skills_played_this_turn` duplicate is always 0 on a state
/// rebuilt from a wire, so a test that sets it would pass while the live arm
/// stayed broken. Bead `sts2-rs-j9x8`.
#[test]
fn make_it_so_late_effect_returns_card_to_hand() {
    use sts2_core::cards::CardType;
    use sts2_core::hooks::CardCtx;

    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    // Play MakeItSo: dispatch handler seeds the per-instance
    // interval (=3) and deals damage.
    let make_it_so_uid = push_play_card(&mut state, CardId::MakeItSo, 7, 0);
    let _ = dispatch(&mut state, CardId::MakeItSo, Some(enemy));
    // Move MakeItSo from Play → Discard, mirroring the cleanup
    // step in `combat_loop::play_card` that runs before the
    // late-effect sweep.
    sts2_core::cards::move_card(
        &mut state.player,
        make_it_so_uid,
        sts2_core::cards::PileKind::Play,
        sts2_core::cards::PileKind::Discard,
    )
    .expect("MakeItSo in Play");
    assert!(state.player.discard.contains(&make_it_so_uid));

    let played_skill = CardCtx {
        card_id: Some(CardId::DefendRegent),
        card_uid: None,
        card_tags: sts2_core::cards::CardTags::NONE,
        card_type: Some(CardType::Skill),
    };

    // 1 skill played: not yet a multiple of 3 → no return to hand.
    // Drive the WIRE-CARRIED bucket: `skills_played_this_turn` is a
    // forward-only duplicate that no reconstructed state ever carries.
    state.player.cards_played_this_turn[CardType::Skill as usize] = 1;
    sts2_core::card_effects::fire_late_effects(&mut state, &played_skill);
    assert!(state.player.discard.contains(&make_it_so_uid));
    assert!(!state.player.hand.contains(&make_it_so_uid));

    // 3 skills played → late-effect fires → MakeItSo returns to
    // hand from Discard.
    state.player.cards_played_this_turn[CardType::Skill as usize] = 3;
    sts2_core::card_effects::fire_late_effects(&mut state, &played_skill);
    assert!(!state.player.discard.contains(&make_it_so_uid));
    assert!(state.player.hand.contains(&make_it_so_uid));
}

/// `MakeItSo`: late-effect ignores Attacks / Powers — only Skills
/// advance the rider. Mirrors Python's
/// `if played.card_type != CardType.SKILL: return` guard.
#[test]
fn make_it_so_late_effect_ignores_non_skill_plays() {
    use sts2_core::cards::CardType;
    use sts2_core::hooks::CardCtx;

    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    let make_it_so_uid = push_play_card(&mut state, CardId::MakeItSo, 7, 0);
    let _ = dispatch(&mut state, CardId::MakeItSo, Some(enemy));
    sts2_core::cards::move_card(
        &mut state.player,
        make_it_so_uid,
        sts2_core::cards::PileKind::Play,
        sts2_core::cards::PileKind::Discard,
    )
    .expect("MakeItSo in Play");

    // Even with 3 Skills played this turn, an Attack-played
    // trigger must not move the card.
    state.player.cards_played_this_turn[CardType::Skill as usize] = 3;
    let played_attack = CardCtx {
        card_id: Some(CardId::StrikeRegent),
        card_uid: None,
        card_tags: sts2_core::cards::CardTags::NONE,
        card_type: Some(CardType::Attack),
    };
    sts2_core::card_effects::fire_late_effects(&mut state, &played_attack);
    assert!(state.player.discard.contains(&make_it_so_uid));
    assert!(!state.player.hand.contains(&make_it_so_uid));
}

/// `MakeItSo`: late-effect is a no-op when the watched card is
/// already in hand. Mirrors Python's `if watched in combat.hand:
/// return` guard.
#[test]
fn make_it_so_late_effect_noop_when_already_in_hand() {
    use sts2_core::cards::CardType;
    use sts2_core::hooks::CardCtx;

    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    let make_it_so_uid = push_play_card(&mut state, CardId::MakeItSo, 7, 0);
    let _ = dispatch(&mut state, CardId::MakeItSo, Some(enemy));
    // Move MakeItSo to Hand (the "already in hand" case).
    sts2_core::cards::move_card(
        &mut state.player,
        make_it_so_uid,
        sts2_core::cards::PileKind::Play,
        sts2_core::cards::PileKind::Hand,
    )
    .expect("MakeItSo in Play");

    let hand_len_before = state.player.hand.len();
    state.player.cards_played_this_turn[CardType::Skill as usize] = 3;
    let played_skill = CardCtx {
        card_id: Some(CardId::DefendRegent),
        card_uid: None,
        card_tags: sts2_core::cards::CardTags::NONE,
        card_type: Some(CardType::Skill),
    };
    sts2_core::card_effects::fire_late_effects(&mut state, &played_skill);
    // No duplicate insertion — hand stays the same length.
    assert_eq!(state.player.hand.len(), hand_len_before);
    assert!(state.player.hand.contains(&make_it_so_uid));
}

