/// `SwordSage` grants every owned Sovereign Blade **Replay 1**: C# v0.107.1
/// `SwordSagePower.AfterPowerAmountChanged` adds the applied amount (1) to
/// each blade's `BaseReplayCount`, so the blade re-resolves its play once
/// more (handled by the engine replay loop). Replaces the v0.103.2 extra-HIT
/// (`SetRepeats`) mechanism.
#[test]
fn sword_sage_grants_sovereign_blade_replay() {
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let player = state.init_player_creature();
    // A Sovereign Blade already exists in combat (forged into hand).
    let _ = combat_forge(&mut state, player, 1, None);

    let _ = push_play_card(&mut state, CardId::SwordSage, 0, 0);
    let _ = dispatch(&mut state, CardId::SwordSage, None);
    assert_eq!(player_has_power(&state, PowerKind::SwordSage), Some(1));

    let blade_uid = *state
        .player
        .hand
        .iter()
        .find(|&&u| state.cards[u.0.get() as usize - 1].card_id == CardId::SovereignBlade)
        .expect("a SovereignBlade exists");
    assert_eq!(
        state.cards[blade_uid.0.get() as usize - 1].base_replay_count,
        1,
        "SwordSage must add Replay 1 to the existing SovereignBlade"
    );
}

/// A Sovereign Blade forged AFTER `SwordSage` is active inherits the power's
/// amount as its `BaseReplayCount`, mirroring C#
/// `SwordSagePower.AfterCardEnteredCombat` (synced in `combat_forge`).
#[test]
fn forge_after_sword_sage_syncs_blade_replay() {
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let player = state.init_player_creature();
    // SwordSage played while NO blade is in combat yet.
    let _ = push_play_card(&mut state, CardId::SwordSage, 0, 0);
    let _ = dispatch(&mut state, CardId::SwordSage, None);
    // Forge now spawns a fresh blade — it must enter with Replay 1.
    let _ = combat_forge(&mut state, player, 5, None);

    let blade_uid = *state
        .player
        .hand
        .iter()
        .find(|&&u| state.cards[u.0.get() as usize - 1].card_id == CardId::SovereignBlade)
        .expect("forge spawned a blade");
    assert_eq!(
        state.cards[blade_uid.0.get() as usize - 1].base_replay_count,
        1,
        "a blade forged under SwordSage(1) must enter combat with Replay 1"
    );
}

/// Parry rework (C# v0.107.1): a Sovereign Blade play gains Block equal to the
/// owner's `ParryPower` amount, granted as a **powered (Move)** block — so
/// Dexterity (and Frail) scale it. `ParryPower(10)` + `Dexterity(3)` → 13
/// Block. (v0.103.2 granted unpowered, Dex/Frail-exempt block.)
#[test]
fn parry_block_onto_sovereign_blade_scales_with_dexterity() {
    crate::cards::dispatch::install_default_registry();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    apply_power_to_player(&mut state, PowerKind::Parry, 10);
    apply_power_to_player(&mut state, PowerKind::Dexterity, 3);
    state.player.block = 0;

    // Play a Sovereign Blade (10 base damage) at the enemy.
    let _ = push_play_card(&mut state, CardId::SovereignBlade, 10, 0);
    let _ = dispatch(&mut state, CardId::SovereignBlade, Some(enemy));

    assert_eq!(
        state.player.block, 13,
        "Parry block (10) onto Sovereign Blade must fold in Dexterity(+3)"
    );
}

