/// Forging when no SovereignBlade exists spawns a fresh blade in
/// hand, and that blade's base_damage is `10 + amount`. Mirrors the
/// Python `combat.forge` path through `make_sovereign_blade()` +
/// loop.
#[test]
fn forge_with_no_blade_spawns_one_and_buffs_it() {
    let (mut state, _e) = fresh_state_with_enemy(50);
    let player = state.init_player_creature();
    assert!(state.player.hand.is_empty());

    let buffed = combat_forge(&mut state, player, 7, None);

    // One blade now in hand, with base_damage = 10 (spec) + 7 = 17.
    assert_eq!(state.player.hand.len(), 1);
    let blade_uid = state.player.hand[0];
    let blade = &state.cards[blade_uid.0.get() as usize - 1];
    assert_eq!(blade.card_id, CardId::SovereignBlade);
    assert_eq!(blade.base_damage, 17);
    // Returned count is post-spawn = 1.
    assert_eq!(buffed, 1);
}

/// Forging twice does not spawn a second blade — the existing
/// blade simply absorbs the second buff. Damage stacks additively.
#[test]
fn forge_twice_buffs_existing_blade_once() {
    let (mut state, _e) = fresh_state_with_enemy(50);
    let player = state.init_player_creature();

    let _ = combat_forge(&mut state, player, 6, None);
    let _ = combat_forge(&mut state, player, 4, None);

    assert_eq!(state.player.hand.len(), 1);
    let blade_uid = state.player.hand[0];
    let blade = &state.cards[blade_uid.0.get() as usize - 1];
    assert_eq!(blade.base_damage, 10 + 6 + 4);
}

/// All non-exhausted SovereignBlade copies receive the buff,
/// regardless of pile (hand / draw / discard / play). Exhausted
/// blades are buffed too (Python `include_exhausted=True` on the
/// buff loop) but do NOT count as "active" for the ensure-step.
#[test]
fn forge_buffs_blades_across_all_piles_including_exhaust() {
    let (mut state, _e) = fresh_state_with_enemy(50);
    let player = state.init_player_creature();

    // Pre-seed one blade in each of draw / discard / exhaust, plus
    // a non-blade decoy in each pile that must remain untouched.
    let in_draw = sts2_core::card_effects::spawn_card_into_pile(
        &mut state,
        card_from_spec(&sspecs::sovereign_blade()),
        PileKind::Draw,
    );
    let in_discard = sts2_core::card_effects::spawn_card_into_pile(
        &mut state,
        card_from_spec(&sspecs::sovereign_blade()),
        PileKind::Discard,
    );
    let in_exhaust = sts2_core::card_effects::spawn_card_into_pile(
        &mut state,
        card_from_spec(&sspecs::sovereign_blade()),
        PileKind::Exhaust,
    );
    let decoy = push_play_card(&mut state, CardId::Shiv, 4, 0);
    let decoy_dmg_before = state.cards[decoy.0.get() as usize - 1].base_damage;

    let buffed = combat_forge(&mut state, player, 5, None);

    // No new blade — the draw-pile blade counts as "active" so the
    // ensure-step is a no-op. All three blades now sit at 10 + 5.
    assert_eq!(buffed, 3);
    for uid in [in_draw, in_discard, in_exhaust] {
        let card = &state.cards[uid.0.get() as usize - 1];
        assert_eq!(card.base_damage, 15, "{:?}", card.card_id);
    }
    // Decoy unchanged.
    assert_eq!(
        state.cards[decoy.0.get() as usize - 1].base_damage,
        decoy_dmg_before
    );
}

/// Exhaust-only blades are NOT counted as active, so a fresh blade
/// gets spawned. Both the new and the exhausted blade then receive
/// the buff (Python's `include_exhausted=True` for the buff loop).
#[test]
fn forge_with_only_exhausted_blade_spawns_new_active_blade() {
    let (mut state, _e) = fresh_state_with_enemy(50);
    let player = state.init_player_creature();

    let exhausted_uid = sts2_core::card_effects::spawn_card_into_pile(
        &mut state,
        card_from_spec(&sspecs::sovereign_blade()),
        PileKind::Exhaust,
    );

    let buffed = combat_forge(&mut state, player, 3, None);

    assert_eq!(buffed, 2, "exhausted + freshly spawned blade both buffed");
    assert_eq!(state.player.hand.len(), 1);
    let new_blade = state.player.hand[0];
    // Both copies sit at 10 + 3.
    assert_eq!(state.cards[new_blade.0.get() as usize - 1].base_damage, 13);
    assert_eq!(
        state.cards[exhausted_uid.0.get() as usize - 1].base_damage,
        13
    );
}

