/// SummonForth: Forge 8 + scan-and-pull existing blades from
/// draw/discard/exhaust. The pre-seeded discard-pile blade lands
/// in hand and is buffed to 10 + 8 = 18 just like any other blade.
#[test]
fn summon_forth_forges_eight_and_pulls_blades() {
    install_pool();
    let (mut state, _e) = fresh_state_with_enemy(200);
    let _ = state.init_player_creature();
    let pre_seeded = sts2_core::card_effects::spawn_card_into_pile(
        &mut state,
        card_from_spec(&sspecs::sovereign_blade()),
        PileKind::Discard,
    );
    let _ = push_play_card(&mut state, CardId::SummonForth, 0, 0);
    let _ = dispatch(&mut state, CardId::SummonForth, None);

    // The pre-seeded blade has been pulled into hand. The forge
    // step happens BEFORE the scan, so the existing blade is
    // already an active blade for the ensure-step (no fresh spawn).
    // After the scan it should sit in hand at base_damage 18.
    assert!(state.player.discard.is_empty());
    let blade = &state.cards[pre_seeded.0.get() as usize - 1];
    assert_eq!(blade.base_damage, 18);
    assert!(state.player.hand.contains(&pre_seeded));
}

/// Begone (bead `sts2-rs-2mltv`, corrected vs `Begone.cs`): Self Skill, NO
/// damage; transforms a chosen hand card into `MinionStrike`. With exactly ONE
/// hand card C# `CardSelectCmd.FromHand(prefs(1))` auto-applies (cards.Count <=
/// MinSelect), so the lone card transforms with no prompt — this test exercises
/// that single-card auto path.
#[test]
fn begone_no_damage_and_transforms_first_hand_card_to_minion_strike() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(100);
    // Seed a non-Begone card into hand so the transformation target
    // is observable. Use Strike-shaped placeholder via push_play_card
    // and re-route it into hand.
    let hand_uid = push_play_card(&mut state, CardId::StrikeIronclad, 6, 0);
    // push_play_card lands the card in `play` for the dispatch
    // smoke; relocate to hand for the Begone transform.
    state.player.play.clear();
    state.player.hand.push(hand_uid);

    // Now seed Begone in play so dispatch fires. Target is ignored
    // (Self), passed only to exercise the dispatch signature.
    let _ = push_play_card(&mut state, CardId::Begone, 0, 0);
    let hp0 = state.creatures[0].current_hp;
    let r = dispatch(&mut state, CardId::Begone, Some(enemy));
    assert_eq!(r, EffectResult::Resolved);
    // No damage — Begone is a Self Skill.
    assert_eq!(hp0 - state.creatures[0].current_hp, 0);
    // Transform half: the original hand uid is gone; a new uid is
    // in its slot whose `card_id == MinionStrike`.
    assert_eq!(
        state.player.hand.len(),
        1,
        "hand still has exactly one card after transform (slot preserved)"
    );
    let new_uid = state.player.hand[0];
    assert_ne!(new_uid, hand_uid, "hand slot rebound to fresh uid");
    let new_card = &state.cards[new_uid.0.get() as usize - 1];
    assert_eq!(new_card.card_id, CardId::MinionStrike);
}

/// Begone with 2+ hand cards: C# `CardSelectCmd.FromHand(prefs(1), filter:
/// null)` opens a single-pick transform-select over the whole hand (no auto-
/// apply). Resolving the choice transforms the CHOSEN card (not blindly the
/// first) into MinionStrike — the whole-run parity fix (seed RP3: the prior
/// pick-first port desynced vs the C# headless agent's pick). Bead
/// `sts2-rs-begone-select`.
#[test]
fn begone_two_hand_cards_opens_transform_choice_and_transforms_chosen() {
    crate::cards::dispatch::install_default_registry();
    // The core-side resolver mints MinionStrike through the registered card
    // factory (registered by the run/relic-dispatch path in real combat).
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    let (mut state, enemy) = fresh_state_with_enemy(100);
    // Seed two distinct, observable hand cards.
    let a = push_hand_card(&mut state, CardId::StrikeRegent);
    let b = push_hand_card(&mut state, CardId::FallingStar);
    let _ = push_play_card(&mut state, CardId::Begone, 0, 0);

    let r = dispatch(&mut state, CardId::Begone, Some(enemy));
    assert_eq!(r, EffectResult::Resolved);
    // 2+ hand cards → a single-pick choice opens (no auto-apply).
    let pc = state
        .pending_choice
        .as_ref()
        .expect("Begone opens a choice");
    assert_eq!(
        pc.kind,
        sts2_core::ChoiceKind::TransformInHandToMinionStrike
    );
    assert_eq!(
        pc.options.len(),
        2,
        "both hand cards are options, in hand order"
    );
    assert_eq!(pc.options[0].card_uid, Some(a));
    assert_eq!(pc.options[1].card_uid, Some(b));

    // Pick option 1 (the SECOND card) — must transform `b`, not the first.
    let selection: SmallVec<[u8; 4]> = [1u8].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    // `a` is untouched; `b`'s slot is rebound to a fresh MinionStrike.
    assert!(state.player.hand.contains(&a), "unchosen card untouched");
    assert!(!state.player.hand.contains(&b), "chosen card slot rebound");
    let minion_uid = *state
        .player
        .hand
        .iter()
        .find(|&&u| u != a)
        .expect("transformed slot present");
    assert_eq!(
        state.cards[minion_uid.0.get() as usize - 1].card_id,
        CardId::MinionStrike,
        "chosen card transformed into MinionStrike",
    );
}

