/// CosmicIndifference (`Begone.cs`-class fix, `sts2-rs-yc2d`): gain block, then
/// `CardSelectCmd.FromSimpleGrid(Discard, prefs(1))` → chosen discard card to
/// draw-pile TOP. With 2+ discard cards a single-pick `PutBack` choice opens
/// (no auto-apply); the block half lands BEFORE the select. Resolving picks the
/// chosen discard card and moves it to draw top — the whole-run parity fix
/// (seed RP18: prior port skipped the select, staying in `combat` vs C#'s
/// `card_select`).
#[test]
fn cosmic_indifference_gains_block_then_opens_discard_putback_choice() {
    crate::cards::dispatch::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(100);
    // Two cards in the discard pile so the select opens (count > MinSelect).
    let d0 = push_hand_card(&mut state, CardId::StrikeRegent);
    let d1 = push_hand_card(&mut state, CardId::FallingStar);
    state.player.hand.clear();
    state.player.discard.extend([d0, d1]);
    // Begone-shaped push: base_block 6 so `current_block` reads 6.
    let _ = push_play_card(&mut state, CardId::CosmicIndifference, 0, 6);
    let blk0 = state.player.block;

    let r = dispatch(&mut state, CardId::CosmicIndifference, None);
    assert_eq!(r, EffectResult::Resolved);
    // Block half is unconditional and happens first.
    assert_eq!(
        state.player.block - blk0,
        6,
        "gains base_block (6) before the select"
    );
    // 2 discard cards → a single-pick PutBack choice opens.
    let pc = state
        .pending_choice
        .as_ref()
        .expect("opens a discard PutBack choice");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::PutBack);
    assert_eq!(
        pc.options.len(),
        2,
        "both discard cards are options, in pile order"
    );

    // Pick option 1 (the SECOND discard card) → moves to draw TOP.
    let selection: SmallVec<[u8; 4]> = [1u8].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    assert_eq!(
        state.player.draw.first().copied(),
        Some(d1),
        "chosen discard card placed on TOP of the draw pile",
    );
    assert!(
        !state.player.discard.contains(&d1),
        "chosen card left the discard pile"
    );
}

/// Bead `sts2-rs-09x5n`: with <=1 discard card, CosmicIndifference AUTO-takes
/// it to draw-top WITHOUT opening a choice (`FromSimpleGrid` short-circuit,
/// mirrors Headbutt's fast path) — and, unlike the earlier port, must PIN
/// the moved card so MCTS PIMC re-shuffles don't scramble a position the
/// player just definitely observed.
#[test]
fn cosmic_indifference_single_discard_auto_takes_and_pins() {
    crate::cards::dispatch::install_default_registry();
    let (mut state, _enemy) = fresh_state_with_enemy(100);
    let d0 = push_hand_card(&mut state, CardId::StrikeRegent);
    state.player.hand.clear();
    state.player.discard.push(d0);
    let _ = push_play_card(&mut state, CardId::CosmicIndifference, 0, 6);

    let r = dispatch(&mut state, CardId::CosmicIndifference, None);
    assert_eq!(r, EffectResult::Resolved);
    assert!(
        state.pending_choice.is_none(),
        "no choice when discard has one card"
    );
    assert_eq!(
        state.player.draw.first().copied(),
        Some(d0),
        "single discard card auto-moved to draw-top"
    );
    assert!(!state.player.discard.contains(&d0), "card left discard");
    assert_eq!(
        state.player.pinned_top.first().copied(),
        Some(d0),
        "CosmicIndifference's <=1-discard fast path must pin the moved card to Top(0)"
    );
}

/// HeirloomHammer with exactly one colorless card in hand (plus some
/// non-colorless cards): deals damage, then auto-clones that single
/// colorless card into hand. Hand grows by one and the new card is a
/// clone of the colorless card (`CardId::DarkShackles`). Mirrors C#
/// `HeirloomHammer.cs` `FromHand(filter: IsColorless, prefs 1)` →
/// `Repeat=1` × `CreateClone()` → `AddGeneratedCardToCombat(.., Hand)`.
/// Beads `sts2-rs-yc2d`, `sts2-rs-vyh1`.
#[test]
fn heirloom_hammer_clones_single_colorless_hand_card() {
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    // Hand: one colorless (DarkShackles) + two non-colorless (StrikeRegent).
    let colorless_uid = push_hand_card(&mut state, CardId::DarkShackles);
    let _ = push_hand_card(&mut state, CardId::StrikeRegent);
    let _ = push_hand_card(&mut state, CardId::StrikeRegent);
    let hand_before = state.player.hand.len();
    let hp0 = state.creatures[0].current_hp;

    let _ = push_play_card(&mut state, CardId::HeirloomHammer, 20, 0);
    let r = dispatch(&mut state, CardId::HeirloomHammer, Some(enemy));
    assert_eq!(r, EffectResult::Resolved);

    // Damage landed.
    assert_eq!(hp0 - state.creatures[0].current_hp, 20);
    // Exactly one card was added to hand (Repeat == 1).
    assert_eq!(state.player.hand.len(), hand_before + 1);
    // The freshly-added hand card is a clone of the colorless card and a
    // distinct instance from the original.
    let new_uid = *state.player.hand.last().expect("hand non-empty");
    assert_ne!(new_uid, colorless_uid, "clone must be a fresh uid");
    let new_card = &state.cards[new_uid.0.get() as usize - 1];
    assert_eq!(new_card.card_id, CardId::DarkShackles);
    // No pending choice surfaced for the single-candidate auto-take path.
    assert!(state.pending_choice.is_none());
}

/// HeirloomHammer with NO colorless card in hand: deals damage but clones
