/// HeirloomHammer's ≥2-colorless branch must clone the SELECTED instance
/// (C# `HeirloomHammer.OnPlay` → `selection.CreateClone()`, a deep copy),
/// preserving a forged SovereignBlade's raised `base_damage` — NOT rebuild
/// a fresh spec card at the blade's base. Parity Regent seed 955
/// (MONSTER_STATE|SOVEREIGN_BLADE): a blade forged to 20 cloned through the
/// shared `AddGeneratedToHand` resolver came back at spec base, so the
/// later blade play dealt 10 less than C# (enemy hp rust=22 vs cs=12). The
/// resolver now honours the option's live `card_uid` and clones its POD.
#[test]
fn heirloom_hammer_choice_clones_forged_blade_instance() {
    use sts2_core::{apply, Action};
    install_pool();
    let (mut state, enemy) = fresh_state_with_enemy(200);
    // Two colorless candidates → opens the choose-a-card screen. Option 0
    // is a forged SovereignBlade (base_damage raised to 20 in combat).
    let blade_uid = push_hand_card(&mut state, CardId::SovereignBlade);
    {
        let idx = blade_uid.0.get() as usize - 1;
        state.cards[idx].base_damage = 20;
    }
    let _ = push_hand_card(&mut state, CardId::DarkShackles);
    let hand_before = state.player.hand.len();

    let _ = push_play_card(&mut state, CardId::HeirloomHammer, 20, 0);
    let _ = dispatch(&mut state, CardId::HeirloomHammer, Some(enemy));

    // ≥2 colorless → choice opened over both candidates.
    let pc = state
        .pending_choice
        .as_ref()
        .expect("≥2 colorless opens a choose-a-card screen");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddGeneratedToHand);
    assert_eq!(pc.options.len(), 2);

    // Resolve picking option 0 (the forged blade).
    let mut sel: SmallVec<[u8; 4]> = SmallVec::new();
    sel.push(0);
    let _ = apply(&mut state, Action::ResolveChoice { selection: sel });
    assert!(state.pending_choice.is_none(), "choice cleared on resolve");

    // A fresh blade was cloned into hand, preserving the forged base_damage.
    assert_eq!(state.player.hand.len(), hand_before + 1);
    let new_uid = *state.player.hand.last().expect("hand non-empty");
    assert_ne!(new_uid, blade_uid, "clone must be a fresh uid");
    let new_card = &state.cards[new_uid.0.get() as usize - 1];
    assert_eq!(new_card.card_id, CardId::SovereignBlade);
    assert_eq!(
        new_card.base_damage, 20,
        "clone preserves the forged base_damage (C# CreateClone), not spec base",
    );
}

